    async pingNode(data, { env, ctx }) {
        const currentConfig = await getRuntimeConfig(env);
        const timeoutMs = clampIntegerConfig(data.timeout, currentConfig.pingTimeout ?? DEFAULT_PING_TIMEOUT_MS, 1000, 180000);
        const requestedProbePath = String(data.probePath || "").trim();

        if (data.target) {
          const normalizedTarget = Database.normalizeSingleTarget(data.target);
          if (!normalizedTarget) return jsonError("INVALID_TARGET", "目标源站必须是有效的 http/https URL");
          const ms = await Database.pingTarget(normalizedTarget, timeoutMs, {
            probePath: requestedProbePath
          });
          return jsonResponse({ ms, target: normalizedTarget, usedCache: false, scope: "target" });
        }

        const nodeName = String(data.name || "").trim();
        const node = await Database.getNode(nodeName, env, ctx);
        if (!node || !Array.isArray(node.lines) || !node.lines.length) return jsonError("NOT_FOUND", "节点不存在");

        const requestedLineId = String(data.lineId || "").trim();
        const linesToProbe = requestedLineId
          ? node.lines.filter(line => line.id === requestedLineId)
          : node.lines.slice();
        if (requestedLineId && !linesToProbe.length) return jsonError("LINE_NOT_FOUND", "线路不存在", 404);

        const probedLines = await Promise.all(linesToProbe.map(async (line) => {
          const ms = await Database.pingTarget(line.target, timeoutMs, {
            probePath: requestedProbePath
          });
          return {
            id: String(line?.id || "").trim(),
            name: String(line?.name || "").trim(),
            target: String(line?.target || "").trim(),
            latencyMs: ms,
            latencyUpdatedAt: new Date().toISOString()
          };
        }));

        const responseLines = node.lines.map(line => {
          const updated = probedLines.find(item => item.id === line.id);
          return updated
            ? {
                id: updated.id,
                name: updated.name,
                target: updated.target,
                latencyMs: updated.latencyMs,
                latencyUpdatedAt: updated.latencyUpdatedAt
              }
            : {
                id: String(line?.id || "").trim(),
                name: String(line?.name || "").trim(),
                target: String(line?.target || "").trim()
              };
        });
        const activeLineId = Database.resolveActiveLineId(node.activeLineId, responseLines, responseLines);
        const activeLine = Database.getActiveNodeLine({
          ...node,
          lines: responseLines,
          activeLineId
        });
        const matchedLine = requestedLineId
          ? responseLines.find(line => line.id === requestedLineId)
          : activeLine;
        const summaryNode = Database.buildNodeSummary(nodeName.toLowerCase(), node).summary || { name: nodeName.toLowerCase() };
        return jsonResponse({
          ms: Number(matchedLine?.latencyMs ?? activeLine?.latencyMs ?? 9999),
          usedCache: false,
          sorted: false,
          activeLineId,
          activeLineName: activeLine?.name || "",
          line: matchedLine || null,
          node: {
            ...summaryNode,
            lines: responseLines,
            activeLineId
          }
        });
  },

  async getLogs(data, { db, env }) {
      if (!db) return jsonResponse({ error: "D1 not configured" }, 500);
      const requestState = LogQueryPlanner.normalizeRequest(data);
      const { filters } = requestState;
      const runtimeConfig = env ? await getRuntimeConfig(env) : {};
      const logReadiness = await Database.resolveLogsReadiness({ db, kv: Database.getKV(env) });
      const searchState = LogQueryPlanner.resolveSearch(filters, runtimeConfig, logReadiness);
      if (searchState.errorResponse) return searchState.errorResponse;
      const { effectiveSearchMode, searchFallbackReason } = searchState;
      const logEnabled = runtimeConfig.logEnabled !== false;
      if (logEnabled !== true) {
        return LogQueryPlanner.buildDisabledResponse(requestState, logReadiness, effectiveSearchMode, searchFallbackReason);
      }
    if (logReadiness.schemaReady !== true) {
      return jsonError("LOG_SCHEMA_NOT_READY", "日志表尚未初始化，请先点击“初始化日志表”", 400, {
        effectiveSearchMode,
        searchFallbackReason,
        revisions: {
          logsRevision: logReadiness.revision
        }
      });
    }
      const sqlPlan = LogQueryPlanner.buildSqlPlan(filters, requestState, runtimeConfig, effectiveSearchMode);
      if (sqlPlan.errorResponse) return sqlPlan.errorResponse;
      const queryResult = await LogQueryPlanner.executeSqlPlan(db, requestState, sqlPlan);
      if (queryResult.errorResponse) return queryResult.errorResponse;
      return LogQueryPlanner.buildSuccessResponse(requestState, logReadiness, {
        logs: queryResult.logs,
        total: queryResult.total,
        totalPages: queryResult.totalPages,
        searchMode: queryResult.searchMode,
        effectiveSearchMode,
        searchFallbackReason,
        hasPrevPage: queryResult.hasPrevPage,
        hasNextPage: queryResult.hasNextPage,
        nextCursor: queryResult.nextCursor
      });
    },

    async clearLogs(data, { db, env, ctx, request }) {
      if (request.headers.get("X-Admin-Confirm") !== "clearLogs") {
        return jsonError("CONFIRMATION_REQUIRED", "敏感操作需要显式确认头", 428);
      }
      if (!db) return jsonResponse({ error: "D1 not configured" }, 500);
      await Database.ensureLogsBaseSchema(db);
      await Database.ensureStatsHourlySchema(db);
      const clearEpochMs = nowMs();
      GLOBALS.LogClearEpochMs = Math.max(GLOBALS.LogClearEpochMs || 0, clearEpochMs);
      await Database.patchOpsStatus(env || db, {
        log: {
          clearEpochMs,
          clearEpochAt: new Date(clearEpochMs).toISOString()
        }
      }, ctx);
      const activeFlushTask = GLOBALS.LogFlushTask;
      if (activeFlushTask) {
        try {
          await activeFlushTask;
        } catch {}
      }
      GLOBALS.LogQueue.length = 0;
      GLOBALS.LogDedupe.clear();
      GLOBALS.LogLastFlushAt = 0;
      await db.prepare(`DELETE FROM ${Database.LOGS_TABLE}`).run();
      await Database.clearStatsHourly(db).catch(() => false);
      let ftsRebuilt = false;
      try {
        ftsRebuilt = await Database.rebuildLogsFts(db);
      } catch (error) {
        console.warn("clearLogs FTS rebuild failed", error);
      }
      const ftsReady = await Database.isLogsFtsReady(db);
      const statsReady = await Database.hasStatsHourlyTable(db);
      const logStatus = await Database.bumpLogsRevision(env || { db }, {
        schemaReady: true,
        ftsReady,
        statsReady,
        clearEpochMs,
        clearEpochAt: new Date(clearEpochMs).toISOString(),
        lastClearAt: new Date().toISOString()
      }, ctx);
      return jsonResponse({
        success: true,
        ftsRebuilt,
        revisions: {
          logsRevision: Database.getLogsRevisionFromStatus(logStatus?.log || logStatus)
        }
      });
    },

