function buildAdminUiContract() {
  return {
    truthSources: {
      primaryUi: "frontend/",
      templateHtml: "frontend/index.html",
      contractDoc: "worker.md"
    },
    bootstrapActions: {
      default: "getAdminBootstrap",
      settings: "getSettingsBootstrap"
    },
    primaryViews: [...ADMIN_PRIMARY_VIEWS],
    settings: {
      visualSections: [...ADMIN_SETTINGS_VISUAL_SECTIONS],
      saveGroups: [...ADMIN_SETTINGS_SAVE_GROUPS]
    }
  };
}

function buildAdminBootstrapPayload(env, initHealth = buildInitHealth(env), config = {}) {
  const adminPath = getAdminPath(env);
  return {
    adminPath,
    loginPath: getAdminLoginPath(env),
    initHealth,
    hostDomain: resolveConfiguredHost(env),
    contract: buildAdminUiContract(),
    shell: buildAdminShellState(env, initHealth, config)
  };
}

function measureAdminShellTemplateBytes() {
  if (cachedAdminTemplateBytes >= 0) return cachedAdminTemplateBytes;
  if (!Array.isArray(ADMIN_HTML_PARTS_PLAIN) || ADMIN_HTML_PARTS_PLAIN.length !== ADMIN_HTML_DYNAMIC_PLACEHOLDERS.length + 1) {
    cachedAdminTemplateBytes = 0;
    return 0;
  }
  const encoder = new TextEncoder();
  let totalBytes = 0;
  for (let index = 0; index < ADMIN_HTML_PARTS_PLAIN.length; index += 1) {
    totalBytes += encoder.encode(String(ADMIN_HTML_PARTS_PLAIN[index] || "")).length;
    if (index < ADMIN_HTML_DYNAMIC_PLACEHOLDERS.length) {
      totalBytes += encoder.encode(ADMIN_HTML_DYNAMIC_PLACEHOLDERS[index]).length;
    }
  }
  cachedAdminTemplateBytes = totalBytes;
  return cachedAdminTemplateBytes;
}

function buildAdminShellLifecycleState(remoteShellConfigured = false, gateState = "") {
  const normalizedGateState = String(gateState || "").trim().toLowerCase();
  if (!remoteShellConfigured) return normalizedGateState === "setup_required" ? "setup_required" : "embedded_only";
  return "remote_ready";
}

function buildAdminShellRetirementState(embeddedFallbackAvailable = false, finalUiHtmlRetired = ADMIN_FINAL_UI_HTML_RETIRED) {
  if (!embeddedFallbackAvailable) return "embedded_fallback_missing";
  return finalUiHtmlRetired ? "embedded_fallback_retained" : "legacy_inline_shell_active";
}

function buildAdminShellEffectiveMode(mode = "embedded", routeState = "") {
  if (String(mode || "").trim().toLowerCase() === "gate" || String(routeState || "").trim() === "setup_gate") {
    return "setup_gate";
  }
  if (String(mode || "").trim().toLowerCase() === "remote") return "remote_shell";
  return String(routeState || "").trim() === "embedded_fallback"
    ? "embedded_fallback"
    : "embedded_shell";
}

function buildAdminEmbeddedFallbackRuntimeState(embeddedFallbackAvailable = false, routeState = "") {
  if (!embeddedFallbackAvailable) return "missing";
  return String(routeState || "").trim() === "embedded_fallback"
    ? "active"
    : "retained";
}

function buildAdminShellState(env, initHealth = buildInitHealth(env), config = {}) {
  const adminIndexState = buildResolvedAdminIndexState(env, config);
  const remoteShellIndexUrl = adminIndexState.indexUrl;
  const embeddedTemplateBytes = measureAdminShellTemplateBytes();
  const remoteShellConfigured = Boolean(remoteShellIndexUrl);
  const embeddedFallbackAvailable = embeddedTemplateBytes > 0;
  let remoteShellOrigin = "";
  if (remoteShellIndexUrl) {
    try {
      remoteShellOrigin = new URL(remoteShellIndexUrl).origin;
    } catch {
      remoteShellOrigin = "";
    }
  }

  return {
    mode: remoteShellConfigured ? "remote-preferred" : "setup_required",
    lifecycleState: buildAdminShellLifecycleState(remoteShellConfigured, adminIndexState.gateState),
    embeddedFallbackState: embeddedFallbackAvailable ? "retained" : "missing",
    retirementState: buildAdminShellRetirementState(embeddedFallbackAvailable),
    gateState: adminIndexState.gateState,
    indexUrl: adminIndexState.indexUrl,
    indexUrlSource: adminIndexState.indexUrlSource,
    effectiveRef: adminIndexState.effectiveRef,
    remoteShellConfigured,
    remoteShellIndexUrl,
    remoteShellOrigin,
    initHealthOk: initHealth?.ok === true,
    embeddedFallbackAvailable,
    embeddedTemplateSource: ADMIN_EMBEDDED_TEMPLATE_MODE,
    embeddedTemplateMode: ADMIN_EMBEDDED_TEMPLATE_MODE,
    embeddedTemplateBytes,
    finalUiHtmlRetired: ADMIN_FINAL_UI_HTML_RETIRED
  };
}

function resolveAdminShellIndexUrl(env, config = {}) {
  return buildResolvedAdminIndexState(env, config).indexUrl;
}

function normalizeAdminShellRuntimeStatus(options = {}) {
  const shellState = isPlainObject(options.shellState) ? options.shellState : {};
  const initHealth = isPlainObject(options.initHealth) ? options.initHealth : {};
  const indexState = isPlainObject(options.indexState) ? options.indexState : {};
  const configuredRemoteIndexUrl = String(options.remoteShellIndexUrl || shellState.remoteShellIndexUrl || indexState.indexUrl || "").trim();
  const normalizedMode = String(options.mode || "").trim().toLowerCase();
  const mode = normalizedMode === "remote" ? "remote" : (normalizedMode === "gate" ? "gate" : "embedded");
  const remoteShellConfigured = shellState.remoteShellConfigured === true || Boolean(configuredRemoteIndexUrl);
  const embeddedFallbackAvailable = shellState.embeddedFallbackAvailable === true;
  const finalUiHtmlRetired = shellState.finalUiHtmlRetired !== false;
  const routeState = String(options.routeState || "").trim() || (mode === "remote" ? "remote_active" : (mode === "gate" ? "setup_gate" : "embedded_active"));
  const lifecycleState = String(options.lifecycleState || shellState.lifecycleState || "").trim()
    || buildAdminShellLifecycleState(remoteShellConfigured, options.gateState || shellState.gateState || indexState.gateState || "");
  const embeddedFallbackState = String(options.embeddedFallbackState || shellState.embeddedFallbackState || "").trim()
    || buildAdminEmbeddedFallbackRuntimeState(embeddedFallbackAvailable, routeState);
  const retirementState = String(options.retirementState || shellState.retirementState || "").trim()
    || buildAdminShellRetirementState(embeddedFallbackAvailable, finalUiHtmlRetired);
  const gateState = String(options.gateState || shellState.gateState || indexState.gateState || (configuredRemoteIndexUrl ? "shell_ready" : "setup_required")).trim() || "setup_required";
  return {
    ...shellState,
    mode,
    effectiveMode: buildAdminShellEffectiveMode(mode, routeState),
    gateState,
    lifecycleState,
    embeddedFallbackState,
    retirementState,
    sourceType: String(options.sourceType || "").trim().toLowerCase() || (mode === "remote" ? "remote_fetch" : (mode === "gate" ? "setup_gate" : "embedded_local")),
    routeState,
    indexUrl: String(options.indexUrl || shellState.indexUrl || indexState.indexUrl || configuredRemoteIndexUrl).trim(),
    indexUrlSource: String(options.indexUrlSource || shellState.indexUrlSource || indexState.indexUrlSource || "").trim(),
    effectiveRef: String(options.effectiveRef || shellState.effectiveRef || indexState.effectiveRef || "").trim(),
    effectiveRefType: String(options.effectiveRefType || shellState.effectiveRefType || indexState.effectiveRefType || "").trim(),
    remoteShellIndexUrl: configuredRemoteIndexUrl,
    remoteShellOrigin: String(shellState.remoteShellOrigin || "").trim(),
    remoteCacheState: String(options.remoteCacheState || "").trim().toLowerCase(),
    revalidateDue: options.revalidateDue === true,
    lastFetchStatus: String(options.lastFetchStatus || "").trim().toLowerCase(),
    reason: String(options.reason || "").trim(),
    requestPath: String(options.requestPath || "").trim(),
    initHealthOk: initHealth.ok === true,
    initHealthMissing: [...new Set((Array.isArray(initHealth.missing) ? initHealth.missing : [])
      .map(item => String(item || "").trim())
      .filter(Boolean))],
    fallbackRetained: embeddedFallbackAvailable,
    templateMode: String(shellState.embeddedTemplateMode || shellState.embeddedTemplateSource || "").trim() || ADMIN_EMBEDDED_TEMPLATE_MODE,
    finalUiHtmlRetired,
    updatedAt: String(options.updatedAt || "").trim() || new Date().toISOString()
  };
}

async function patchAdminShellRuntimeStatus(envOrStore, options = {}, ctx = null) {
  const shellState = isPlainObject(options.shellState)
    ? options.shellState
    : buildAdminShellState(envOrStore, options.initHealth, options.config || {});
  const statusPatch = normalizeAdminShellRuntimeStatus({
    ...options,
    shellState
  });
  const stores = Database.resolveOpsStatusStores(envOrStore);
  const db = stores.db;
  const { updatedAt: _updatedAt, ...stableStatusPatch } = statusPatch;
  const fingerprint = hashStableText(serializeConfigValue(stableStatusPatch));
  const previousState = db ? GLOBALS.AdminShellStatusWriteState.get(db) : null;
  const stableWriteIntervalMs = Math.max(
    1000,
    Number(Config.Defaults.AdminShellStatusStableWriteIntervalMs) || 1000
  );
  if (options.throttleStableWrites === true && previousState?.fingerprint === fingerprint) {
    if (previousState.writePromise) return previousState.writePromise;
    if ((nowMs() - (Number(previousState.writtenAt) || 0)) < stableWriteIntervalMs) {
      return null;
    }
  }

  const writePromise = withNonCriticalFallback(
    Promise.resolve(Database.patchOpsStatus(envOrStore, { adminShell: statusPatch }, ctx))
      .then(result => ({ ok: true, result })),
    "admin.shell_status_patch",
    {
      requestPath: statusPatch.requestPath,
      mode: statusPatch.mode,
      sourceType: statusPatch.sourceType
    },
    { ok: false, result: null }
  );
  const trackedWritePromise = writePromise.then(outcome => {
    if (!db) return outcome?.result ?? null;
    const currentState = GLOBALS.AdminShellStatusWriteState.get(db);
    if (currentState?.writePromise !== trackedWritePromise) return outcome?.result ?? null;
    if (outcome?.ok === true) {
      GLOBALS.AdminShellStatusWriteState.set(db, {
        fingerprint,
        writtenAt: nowMs(),
        writePromise: null
      });
    } else if (previousState) {
      GLOBALS.AdminShellStatusWriteState.set(db, previousState);
    } else {
      GLOBALS.AdminShellStatusWriteState.delete(db);
    }
    return outcome?.result ?? null;
  });
  if (db) {
    GLOBALS.AdminShellStatusWriteState.set(db, {
      fingerprint,
      writtenAt: 0,
      writePromise: trackedWritePromise
    });
  }
  return trackedWritePromise;
}

function withAdminShellRuntimeStatus(runtimeStatus = {}, env, config = {}, initHealth = buildInitHealth(env)) {
  const safeRuntimeStatus = isPlainObject(runtimeStatus) ? runtimeStatus : {};
  const adminIndexState = buildResolvedAdminIndexState(env, config);
  const shellState = buildAdminShellState(env, initHealth, config);
  return {
    ...safeRuntimeStatus,
    adminShell: normalizeAdminShellRuntimeStatus({
      ...(isPlainObject(safeRuntimeStatus.adminShell) ? safeRuntimeStatus.adminShell : {}),
      shellState,
      initHealth,
      indexState: adminIndexState,
      remoteShellIndexUrl: adminIndexState.indexUrl,
      gateState: adminIndexState.gateState,
      indexUrl: adminIndexState.indexUrl,
      indexUrlSource: adminIndexState.indexUrlSource,
      effectiveRef: adminIndexState.effectiveRef,
      effectiveRefType: adminIndexState.effectiveRefType,
      mode: isPlainObject(safeRuntimeStatus.adminShell) && String(safeRuntimeStatus.adminShell.mode || "").trim()
        ? safeRuntimeStatus.adminShell.mode
        : (adminIndexState.indexUrl ? "remote" : "gate"),
      routeState: isPlainObject(safeRuntimeStatus.adminShell) && String(safeRuntimeStatus.adminShell.routeState || "").trim()
        ? safeRuntimeStatus.adminShell.routeState
        : (adminIndexState.indexUrl ? "remote_ready_idle" : "setup_gate"),
      sourceType: isPlainObject(safeRuntimeStatus.adminShell) && String(safeRuntimeStatus.adminShell.sourceType || "").trim()
        ? safeRuntimeStatus.adminShell.sourceType
        : (adminIndexState.indexUrl ? "runtime_status" : "setup_gate")
    })
  };
}

function describeAdminRemoteShellFailureReason(reason = "") {
  const normalizedReason = String(reason || "").trim();
  if (!normalizedReason) {
    return "已上传的管理台 HTML 暂时不可用，请重新上传。";
  }
  if (normalizedReason.startsWith("remote_shell_render_failed")) {
    const detail = normalizedReason.replace(/^remote_shell_render_failed:\s*/i, "").trim();
    return detail
      ? `Worker 读取 index.html 失败：${detail}`
      : "Worker 读取 index.html 失败。";
  }
  return normalizedReason;
}

